import fs from 'node:fs';
import { pathToFileURL } from 'node:url';

/**
 * Select and serialize complete context sections within a UTF-8 byte budget.
 */
export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }

  const seenIds = new Set();
  const records = [];
  const hasOwn = Object.prototype.hasOwnProperty;

  // Validate and prepare every entry before making any packing decision.
  for (let index = 0; index < sections.length; index += 1) {
    if (!hasOwn.call(sections, index)) {
      throw new Error('sections must be a dense array');
    }

    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('each section must be a non-null, non-array object');
    }
    for (const field of ['id', 'text', 'priority', 'required']) {
      if (!hasOwn.call(section, field)) {
        throw new Error(`section is missing required field: ${field}`);
      }
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      throw new Error('section id must be a nonempty string');
    }
    if (seenIds.has(section.id)) {
      throw new Error(`duplicate section id: ${section.id}`);
    }
    seenIds.add(section.id);
    if (typeof section.text !== 'string') {
      throw new Error('section text must be a string');
    }
    if (!Number.isSafeInteger(section.priority) || section.priority < 0) {
      throw new Error('section priority must be a nonnegative safe integer');
    }
    if (typeof section.required !== 'boolean') {
      throw new Error('section required must be a boolean');
    }

    const frame = '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';
    records.push({
      id: section.id,
      priority: section.priority,
      required: section.required,
      index,
      frame,
      cost: Buffer.byteLength(frame, 'utf8')
    });
  }

  const required = records.filter((record) => record.required);
  let bytes = 0;
  for (const record of required) {
    if (record.cost > maxBytes - bytes) {
      throw new Error('required sections exceed maxBytes');
    }
    bytes += record.cost;
  }

  const selected = [...required];
  const includedIndexes = new Set(required.map((record) => record.index));
  const optional = records.filter((record) => !record.required);
  optional.sort((left, right) => {
    if (left.priority !== right.priority) {
      return left.priority > right.priority ? -1 : 1;
    }
    return left.index - right.index;
  });

  for (const record of optional) {
    if (record.cost <= maxBytes - bytes) {
      selected.push(record);
      includedIndexes.add(record.index);
      bytes += record.cost;
    }
  }

  return {
    text: selected.map((record) => record.frame).join(''),
    bytes,
    included: selected.map((record) => record.id),
    omitted: records
      .filter((record) => !record.required && !includedIndexes.has(record.index))
      .map((record) => record.id)
  };
}

function runCli() {
  if (process.argv.length !== 3) {
    throw new Error('usage: node context-packet.js INPUT_JSON_FILE');
  }
  const input = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('input JSON must be an object');
  }
  const result = packContext(input.sections, input.maxBytes);
  process.stdout.write(JSON.stringify(result) + '\n');
}

const isMain = process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;

if (isMain) {
  try {
    runCli();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write((message || 'error') + '\n');
    process.exitCode = 2;
  }
}

