import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {packContext} from './context-packet.js';

const valid={id:'__proto__\u0000雪',text:'é\n',priority:Number.MAX_SAFE_INTEGER,required:false};
const frame='### '+JSON.stringify(valid.id)+'\n'+valid.text+'\n';
assert.deepEqual(packContext([valid],Buffer.byteLength(frame)),{text:frame,bytes:Buffer.byteLength(frame),included:[valid.id],omitted:[]});
assert.throws(()=>packContext([],Number.MAX_SAFE_INTEGER+1),Error);
assert.throws(()=>packContext([{id:'x',text:'x',priority:Number.MAX_SAFE_INTEGER+1,required:false}],100),Error);
assert.throws(()=>packContext([{id:'x',text:'x',priority:0}],100),Error);

const dir=fs.mkdtempSync(path.join(os.tmpdir(),'context-packet-'));
try {
  const good=path.join(dir,'good.json');
  fs.writeFileSync(good,JSON.stringify({sections:[valid],maxBytes:Buffer.byteLength(frame),ignored:true}));
  const ok=spawnSync(process.execPath,['context-packet.js',good],{encoding:'utf8'});
  assert.equal(ok.status,0); assert.equal(ok.stderr,'');
  assert.deepEqual(JSON.parse(ok.stdout),packContext([valid],Buffer.byteLength(frame)));
  assert.ok(ok.stdout.endsWith('\n'));
  for (const args of [[],[good,good],[path.join(dir,'missing')]]) {
    const bad=spawnSync(process.execPath,['context-packet.js',...args],{encoding:'utf8'});
    assert.equal(bad.status,2); assert.equal(bad.stdout,''); assert.ok(bad.stderr.length>0);
  }
} finally { fs.rmSync(dir,{recursive:true,force:true}); }
console.log('extended API and CLI checks passed');
EOF

